list_shipping_rates.code:
var response = await client.ShippingRates.ListShippingRatesAsync(
    new Dictionary<string, object?> { ["method"] = "flat_rate", ["handling_cost"] = "with_handling", ["sort"] = "name", ["order"] = "asc" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var rate in ((IReadOnlyList<object?>)body["shipping_rates"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{rate["id"]} {rate["name"]} {rate["method"]} {rate["calculate_for_entire_order"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");

