    {
        ["name"] = "Flat 10", ["method"] = "flat_rate",
        ["shipping_cost"] = new Dictionary<string, object?> { ["amount"] = 10, ["type"] = "fixed" },
        ["handling_cost"] = new Dictionary<string, object?> { ["amount"] = 5, ["type"] = "percent" },
    },
